import java.io.*;import java.util.*;public class Main {static class FastScanner {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st;String next() {while (st == null || !st.hasMoreTokens()) {try {String l = br.readLine();if (l == null) return null;st = new StringTokenizer(l);} catch (IOException e) {return null;}}return st.nextToken();}int nextInt() {return Integer.parseInt(next());}long nextLong() {return Long.parseLong(next());}}public static void main(String[] args) {FastScanner sc = new FastScanner();int n = sc.nextInt();long t = sc.nextLong();int[] a = new int[n];for (int i = 0; i < n; i++) {a[i] = sc.nextInt();}int left = 0;long currentSum = 0;int maxBooks = 0;for (int right = 0; right < n; right++) {currentSum += a[right];while (currentSum > t && left <= right) {currentSum -= a[left];left++;}maxBooks = Math.max(maxBooks, right - left + 1);}System.out.println(maxBooks);}}